        "proof-bundle.evaluatorClosure": "The evaluation-seal.evaluatorClosure."
      },
      "selectedThroughOtherInput": {
        "import.producerClosure": "plan.importIds, which retains the import record naming them; an import named by proof.evaluationInputRefs must itself be a plan.importIds member (UNSELECTED_EVALUATION_IMPORT).",
        "import.adapterClosure": "plan.importIds, which retains the import record naming them; an import named by proof.evaluationInputRefs must itself be a plan.importIds member (UNSELECTED_EVALUATION_IMPORT).",
